('lib/content/pa_scolarite/policier_intervention_pages/patrouille/signalement_descriptif_page.dart','f00021','II — Signalement d’une personne',21,'string','4) Corpulence : mince/maigre/svelte — normale — trapue — forte.','4) Corpulence : mince/maigre/svelte — normale — trapue — forte.','{}'::jsonb,true),
